using System.Collections.Generic;
using PhaseX.Station;
using UnityEngine;

/// <summary>
/// Loads the Blender-made 3D models (.fbx) from Resources/Models and puts them in the scene with the game's own
/// URP materials. Every model uses standard material names (Mat_GoldFoil, Mat_Alu, Mat_GlowCyan, ...); the library
/// swaps each one for the matching runtime material from PhaseXMaterials, so shaders work in the editor and in builds.
/// Folders: Spacecraft/ (one model per part id), Rockets/ (one per launch vehicle id), Simulation/, Station/.
/// The models are generated by the scripts in Tools/BlenderModels.
/// </summary>
public static class PhaseXModelLibrary
{
    /// <summary>Every launch vehicle model stands on y = 0 and is exactly this tall.</summary>
    public const float RocketModelHeight = 1.6f;
    public const string PlanetSphere = "Simulation/planet_sphere_highres";

    static readonly Dictionary<string, GameObject> Prefabs = new Dictionary<string, GameObject>();
    static readonly Dictionary<string, Material> Materials = new Dictionary<string, Material>();
    static readonly HashSet<string> Reported = new HashSet<string>();
    static readonly Dictionary<string, Dictionary<string, AnimationClip>> ClipSets = new Dictionary<string, Dictionary<string, AnimationClip>>();

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void ResetStatics()
    {
        Prefabs.Clear();
        Materials.Clear();
        Reported.Clear();
        ClipSets.Clear();
    }

    /// <summary>The animation clips inside a model file, by name ("Idle", "Walk", ...). Empty for a static model.</summary>
    public static Dictionary<string, AnimationClip> Clips(string modelPath)
    {
        if (ClipSets.TryGetValue(modelPath ?? "", out var set)) return set;
        set = new Dictionary<string, AnimationClip>();
        if (!string.IsNullOrEmpty(modelPath))
            foreach (var clip in Resources.LoadAll<AnimationClip>("Models/" + modelPath))
                if (clip != null && !clip.name.StartsWith("__preview__")) set[clip.name] = clip;
        ClipSets[modelPath ?? ""] = set;
        return set;
    }

    public static AnimationClip Clip(string modelPath, string clipName) =>
        Clips(modelPath).TryGetValue(clipName, out var clip) ? clip : null;

    /// <summary>True for a model that carries animation clips (it is instantiated with its Animator kept).</summary>
    public static bool IsAnimated(string modelPath) => Clips(modelPath).Count > 0;

    /// <summary>The imported model, or null if Resources/Models/&lt;modelPath&gt; does not exist.</summary>
    public static GameObject Load(string modelPath)
    {
        if (string.IsNullOrEmpty(modelPath)) return null;
        if (Prefabs.TryGetValue(modelPath, out var cached) && cached != null) return cached;
        var prefab = Resources.Load<GameObject>("Models/" + modelPath);
        Prefabs[modelPath] = prefab;
        return prefab;
    }

    public static bool Has(string modelPath) => Load(modelPath) != null;

    /// <summary>
    /// Instantiate a model under <paramref name="parent"/> and bind its materials. Colliders, lights, cameras and
    /// animators that an import may have added are removed. <paramref name="ledA"/>, <paramref name="ledB"/> and
    /// <paramref name="rtgGlow"/> are the caller's animated materials for Mat_LedA, Mat_LedB and Mat_RtgGlow.
    /// A missing model is reported once and an empty object is returned, so callers never get null.
    /// <para>An animated model (one with clips) keeps its Animator and is returned inside a holder object: position,
    /// rotation and scale go on the holder, and the imported rig below it keeps the transforms its clips expect.
    /// Play its clips with <see cref="PhaseXClipPlayer"/> or a PlayableGraph on the Animator in its children.</para>
    /// </summary>
    public static GameObject InstantiateModel(string modelPath, Transform parent, Vector3 localPos = default, Quaternion localRot = default,
        Vector3? localScale = null, Material ledA = null, Material ledB = null, Material rtgGlow = null)
    {
        var prefab = Load(modelPath);
        string name = modelPath.Substring(modelPath.LastIndexOf('/') + 1);
        GameObject go;
        if (prefab == null)
        {
            if (Reported.Add(modelPath))
                Debug.LogError($"[PhaseX] 3D model \"Resources/Models/{modelPath}.fbx\" is missing. Re-run the scripts in Tools/BlenderModels.");
            go = new GameObject(name);
            go.transform.SetParent(parent, false);
        }
        else if (IsAnimated(modelPath))
        {
            go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rig = Object.Instantiate(prefab, go.transform, false);
            rig.name = name + "_Rig";
            var animator = rig.GetComponent<Animator>();
            if (animator == null) animator = rig.AddComponent<Animator>();
            animator.applyRootMotion = false;
        }
        else
        {
            go = Object.Instantiate(prefab, parent, false);
            go.name = name;
        }
        var t = go.transform;
        t.localPosition = localPos;
        // "default" for a Quaternion is all zeros, which is not a rotation
        t.localRotation = localRot.x == 0f && localRot.y == 0f && localRot.z == 0f && localRot.w == 0f ? Quaternion.identity : localRot;
        t.localScale = localScale ?? Vector3.one;

        foreach (var c in go.GetComponentsInChildren<Collider>(true)) StationKit.Kill(c);
        foreach (var c in go.GetComponentsInChildren<Light>(true)) StationKit.Kill(c);
        foreach (var c in go.GetComponentsInChildren<Camera>(true)) StationKit.Kill(c);
        if (!IsAnimated(modelPath))      // animated models keep their Animator; a static one never needs it
            foreach (var c in go.GetComponentsInChildren<Animator>(true)) StationKit.Kill(c);
        BindMaterials(go, ledA, ledB, rtgGlow);
        return go;
    }

    /// <summary>Replace every imported material by the runtime URP material with the same standard name.</summary>
    public static void BindMaterials(GameObject root, Material ledA = null, Material ledB = null, Material rtgGlow = null)
    {
        foreach (var r in root.GetComponentsInChildren<Renderer>(true))
        {
            var mats = r.sharedMaterials;
            for (int i = 0; i < mats.Length; i++)
                mats[i] = MaterialFor(mats[i] != null ? mats[i].name : "", ledA, ledB, rtgGlow);
            r.sharedMaterials = mats;
        }
    }

    /// <summary>Find a child by name anywhere under <paramref name="root"/> (inactive children included).</summary>
    public static Transform Find(Transform root, string name)
    {
        if (root == null) return null;
        foreach (var t in root.GetComponentsInChildren<Transform>(true))
            if (t.name == name) return t;
        return null;
    }

    /// <summary>The renderer of a named child (the child itself, or the first one below it).</summary>
    public static Renderer FindRenderer(Transform root, string name)
    {
        var t = Find(root, name);
        return t != null ? t.GetComponentInChildren<Renderer>(true) : null;
    }

    /// <summary>
    /// A smooth 64 x 32 sphere of diameter 1 (the same size as Unity's sphere primitive) with one material:
    /// Earth, Moon, cloud and atmosphere shells.
    /// </summary>
    public static Transform Sphere(Transform parent, string name, Vector3 localPos, Vector3 localScale, Vector3 euler, Material mat)
    {
        GameObject go;
        if (Has(PlanetSphere))
        {
            go = InstantiateModel(PlanetSphere, parent, localPos, Quaternion.Euler(euler), localScale);
            foreach (var r in go.GetComponentsInChildren<Renderer>(true)) r.sharedMaterial = mat;
        }
        else
        {
            go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            StationKit.Kill(go.GetComponent<Collider>());
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localRotation = Quaternion.Euler(euler);
            go.transform.localScale = localScale;
            go.GetComponent<Renderer>().sharedMaterial = mat;
        }
        go.name = name;
        return go.transform;
    }

    public static void SetLayer(GameObject root, int layer)
    {
        foreach (var t in root.GetComponentsInChildren<Transform>(true)) t.gameObject.layer = layer;
    }

    // ------------------------------------------------------------------ standard materials

    static Material Glow(Color c, float intensity = 2.2f)
    {
        Color b = c * 0.35f; b.a = 1f;
        return PhaseXMaterials.Lit(b, 0.5f, 0f, c * intensity);
    }

    /// <summary>The runtime material for a standard material name ("Mat_GoldFoil", also "Mat_GoldFoil.001").</summary>
    public static Material MaterialFor(string materialName, Material ledA = null, Material ledB = null, Material rtgGlow = null)
    {
        string key = materialName ?? "";
        int cut = key.IndexOfAny(new[] { '.', ' ' });
        if (cut > 0) key = key.Substring(0, cut);
        if (key == "Mat_LedA" && ledA != null) return ledA;
        if (key == "Mat_LedB" && ledB != null) return ledB;
        if (key == "Mat_RtgGlow" && rtgGlow != null) return rtgGlow;
        if (Materials.TryGetValue(key, out var m) && m != null) return m;

        switch (key)
        {
            case "Mat_GoldFoil": m = PhaseXMaterials.Lit(new Color(0.86f, 0.64f, 0.2f), 0.86f, 0.95f); break;
            case "Mat_GoldDark": m = PhaseXMaterials.Lit(new Color(0.66f, 0.46f, 0.12f), 0.7f, 0.9f); break;
            case "Mat_Alu": m = PhaseXMaterials.Lit(new Color(0.74f, 0.76f, 0.8f), 0.65f, 0.85f); break;
            case "Mat_Silver": m = PhaseXMaterials.Lit(new Color(0.82f, 0.84f, 0.88f), 0.88f, 1f); break;
            case "Mat_White": m = PhaseXMaterials.Lit(new Color(0.9f, 0.9f, 0.92f), 0.6f, 0.2f); break;
            case "Mat_Dark": m = PhaseXMaterials.Lit(new Color(0.1f, 0.1f, 0.12f), 0.55f, 0.6f); break;
            case "Mat_Carbon": m = PhaseXMaterials.Lit(new Color(0.06f, 0.06f, 0.07f), 0.55f, 0.3f); break;
            case "Mat_Bronze": m = PhaseXMaterials.Lit(new Color(0.72f, 0.45f, 0.2f), 0.7f, 0.85f); break;
            case "Mat_SolarCell": m = PhaseXMaterials.Lit(new Color(0.05f, 0.12f, 0.42f), 0.92f, 0.45f); break;
            case "Mat_EngineBell": m = PhaseXMaterials.Lit(new Color(0.2f, 0.2f, 0.22f), 0.55f, 0.8f); break;
            case "Mat_Beryllium": m = PhaseXMaterials.Lit(new Color(0.62f, 0.64f, 0.66f), 0.7f, 0.85f); break;
            case "Mat_Glass": m = PhaseXMaterials.Lit(new Color(0.02f, 0.03f, 0.08f), 0.96f, 0.3f, new Color(0.03f, 0.1f, 0.18f)); break;
            case "Mat_SteelRed": m = PhaseXMaterials.Lit(new Color(0.35f, 0.12f, 0.08f), 0.4f, 0.5f); break;
            case "Mat_FlagRed": m = PhaseXMaterials.Lit(new Color(0.75f, 0.1f, 0.12f), 0.4f, 0f); break;
            case "Mat_FlagBlue": m = PhaseXMaterials.Lit(new Color(0.1f, 0.15f, 0.5f), 0.4f, 0f); break;
            case "Mat_Metal": m = PhaseXMaterials.Lit(new Color(0.16f, 0.18f, 0.22f), 0.55f, 0.6f); break;
            case "Mat_Grey": m = PhaseXMaterials.Lit(new Color(0.42f, 0.44f, 0.47f), 0.45f, 0.6f); break;
            case "Mat_Screen": m = PhaseXMaterials.Lit(new Color(0.02f, 0.05f, 0.09f), 0.8f, 0f, new Color(0.02f, 0.1f, 0.18f)); break;
            case "Mat_GlowCyan": m = Glow(new Color(0.2f, 0.85f, 1f)); break;
            case "Mat_GlowAmber": m = Glow(new Color(1f, 0.68f, 0.18f)); break;
            case "Mat_GlowGreen": m = Glow(new Color(0.2f, 1f, 0.45f)); break;
            case "Mat_GlowRed": m = Glow(new Color(1f, 0.25f, 0.2f)); break;
            case "Mat_GlowBlue": m = Glow(new Color(0.35f, 0.6f, 1f), 2.6f); break;
            case "Mat_GlowOrange": m = Glow(new Color(1f, 0.5f, 0.15f)); break;
            case "Mat_LedA": m = Glow(new Color(0.3f, 1f, 0.5f), 2.5f); break;
            case "Mat_LedB": m = Glow(new Color(1f, 0.68f, 0.18f), 2.5f); break;
            case "Mat_RtgGlow": m = Glow(new Color(1f, 0.42f, 0.1f)); break;
            case "Mat_Beam": m = StationKit.Ghost(new Color(0.3f, 0.8f, 1f, 0.07f)); break;
            case "Mat_Wall": m = PhaseXMaterials.Lit(new Color(0.17f, 0.2f, 0.25f), 0.35f, 0.1f); break;
            case "Mat_WallDark": m = PhaseXMaterials.Lit(new Color(0.1f, 0.115f, 0.145f), 0.4f, 0.2f); break;
            case "Mat_Ceiling": m = PhaseXMaterials.Lit(new Color(0.07f, 0.08f, 0.1f), 0.3f, 0.1f); break;
            case "Mat_Trim": m = PhaseXMaterials.Lit(new Color(0.05f, 0.055f, 0.07f), 0.6f, 0.6f); break;
            // effect meshes: a white-hot opaque core inside alpha-blended flame layers
            case "Mat_FxCore": m = PhaseXMaterials.Lit(new Color(1f, 0.9f, 0.7f), 0.5f, 0f, new Color(5f, 4.2f, 2.6f)); break;
            case "Mat_FxFlame": m = StationKit.Ghost(new Color(1f, 0.58f, 0.16f, 0.62f)); break;
            case "Mat_FxOuter": m = StationKit.Ghost(new Color(1f, 0.32f, 0.08f, 0.26f)); break;
            case "Mat_FxPuff": m = StationKit.Ghost(new Color(0.9f, 0.95f, 1f, 0.42f)); break;
            default:
                if (Reported.Add("material:" + key))
                    Debug.LogWarning($"[PhaseX] Model material \"{materialName}\" has no runtime material in PhaseXModelLibrary; using aluminium.");
                m = PhaseXMaterials.Lit(new Color(0.74f, 0.76f, 0.8f), 0.65f, 0.85f);
                break;
        }
        Materials[key] = m;
        return m;
    }
}
